0430\u0301\u0440\u043d\u044b\u0435 \u043b\u0430\u0441\u043a\u0430\u0301\u043b\u0438 \u0441\u043e\u0431\u0430\u0301\u043a\u0443 \u0438 \u043e\u0441\u043c\u0430\u0301\u0442\u0440\u0438\u0432\u0430\u043b\u0438 \u0435\u0451 - \u043d\u0435 \u043e\u0431\u0433\u043e\u0440\u0435\u0301\u043b\u0430 \u043b\u0438 \u043e\u043d\u0430\u0301; \u043d\u043e \u0411\u043e\u0431 \u0440\u0432\u0430\u043b\u0441\u044f \u043e\u043f\u044f\u0442\u044c \u0432 \u0434\u043e\u043c. \u041f\u043e\u0436\u0430\u0301\u0440\u043d\u044b\u0435 \u043f\u043e\u0434\u0443\u0301\u043c\u0430\u043b\u0438, \u0447\u0442\u043e \u0432 \u0434\u043e\u0301\u043c\u0435 \u0435\u0441\u0442\u044c \u0435\u0449\u0451 \u0447\u0442\u043e-\u043d\u0438\u0431\u0443\u0301\u0434\u044c \u0436\u0438\u0432\u043e\u0301\u0435, \u0438 \u043f\u0443\u0441\u0442\u0438\u0301\u043b\u0438 \u0435\u0433\u043e\u0301. \u0421\u043e\u0431\u0430\u0301\u043a\u0430 \u043f\u043e\u0431\u0435\u0436\u0430\u0301\u043b\u0430 \u0432 \u0434\u043e\u043c \u0438 \u0441\u043a\u043e\u0301\u0440\u043e \u0432\u044b\u0301\u0431\u0435\u0436\u0430\u043b\u0430 \u0441 \u0447\u0435\u043c-\u0442\u043e \u0432 \u0437\u0443\u0431\u0430\u0301\u0445. \u041a\u043e\u0433\u0434\u0430\u0301 \u043d\u0430\u0440\u043e\u0301\u0434 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u0301\u043b \u0442\u043e, \u0447\u0442\u043e \u043e\u043d\u0430\u0301 \u043d\u0435\u0441\u043b\u0430\u0301, \u0442\u043e \u0432\u0441\u0435 \u0440\u0430\u0441\u0445\u043e\u0445\u043e\u0442\u0430\u0301\u043b\u0438\u0441\u044c: \u043e\u043d\u0430\u0301 \u043d\u0435\u0441\u043b\u0430\u0301 \u0431\u043e\u043b\u044c\u0448\u0443\u0301\u044e \u043a\u0443\u0301\u043a\u043b\u0443."
    val READING_SPAN = "\u0443\u0441\u0442\u0430\u0432 \u043f\u0438\u0441\u0430\u0442\u044c \u043b\u043e\u0436\u0438\u043b\u0441\u044f \u043d\u0430\u00a0\u0434\u0438\u0432\u0430\u043d \u0438\u00a0\u043e\u0442\u0434\u044b\u0445\u0430\u043b \u0447\u0438\u0442\u0430\u044f, \u043f\u043e\u0442\u043e\u043c \u043e\u043f\u044f\u0442\u044c \u0441\u0430\u0434\u0438\u043b\u0441\u044f \u043f\u0438\u0441\u0430\u0442\u044c, \u0438\u00a0\u0443\u0440\u044b\u0432\u043a\u0430\u043c\u0438 \u043c\u0435\u0436\u0434\u0443 \u044d\u0442\u0438\u0445 \u0437\u0430\u043d\u044f\u0442\u0438\u0439 \u0443\u0441\u043b\u044b\u0448\u0430\u043b \u0443\u0442\u0440\u043e\u043c \u0433\u043e\u043b\u043e\u0441 \u0441\u0442\u0430\u0440\u0443\u0448\u043a\u0438, \u0445\u043e\u0437\u044f\u0439\u043a\u0438 \u0434\u043e\u043c\u0438\u043a\u0430: \u00ab\u0441\u0430\u043c\u043e\u0432\u0430\u0440 \u043f\u0440\u0438\u043d\u0435\u0441\u043b\u0430, \u041f\u0430\u0432\u0435\u043b \u0421\u0435\u0440\u0433\u0435\u0435\u0432\u0438\u0447\u00bb, \u0441\u043a\u0430\u0437\u0430\u043b \u0435\u0439 \u00ab\u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044e, \u0410\u043d\u043d\u0430 \u0414\u0430\u043d\u0438\u043b\u043e\u0432\u043d\u0430\u00bb, \u0432\u044b\u043f\u0438\u043b \u0434\u0432\u0430 \u0441\u0442\u0430\u043a\u0430\u043d\u0430 \u0447\u0430\u044e \u0441\u00a0\u043c\u043e\u043b\u043e\u043a\u043e\u043c, \u0441\u044a\u0435\u043b \u0441\u00a0\u0447\u0430\u0435\u043c \u043b\u043e\u043c\u043e\u0442\u044c \u0431\u0435\u043b\u043e\u0433\u043e \u0445\u043b\u0435\u0431\u0430; \u043e\u043f\u044f\u0442\u044c \u0443\u0441\u043b\u044b\u0448\u0430\u043b \u0433\u043e\u043b\u043e\u0441 \u0445\u043e\u0437\u044f\u0439\u043a\u0438: \u00ab\u043f\u0440\u0438\u043d\u0435\u0441\u043b\u0430 \u0437\u0430\u0432\u0442\u0440\u0430\u043a, \u041f\u0430\u0432\u0435\u043b \u0421\u0435\u0440\u0433\u0435\u0435\u0432\u0438\u0447\u00bb, \u043e\u043f\u044f\u0442\u044c \u043f\u043e\u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u0438\u043b \u0435\u0435, \u0432\u044b\u043f\u0438\u043b \u0441\u0442\u0430\u043a\u0430\u043d \u043c\u043e\u043b\u043e\u043a\u0430 \u0441\u00a0\u0447\u0435\u0440\u043d\u044b\u043c \u0445\u043b\u0435\u0431\u043e\u043c, \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0432\u0448\u0438\u0439 \u0435\u0433\u043e \u0437\u0430\u0432\u0442\u0440\u0430\u043a, \u043e\u043f\u044f\u0442\u044c \u0443\u0441\u043b\u044b\u0448\u0430\u043b \u0433\u043e\u043b\u043e\u0441 \u0445\u043e\u0437\u044f\u0439\u043a\u0438: \u00ab\u043f\u0440\u0438\u043d\u0435\u0441\u043b\u0430 \u043e\u0431\u0435\u0434, \u041f\u0430\u0432\u0435\u043b \u0421\u0435\u0440\u0433\u0435\u0438\u0447\u00bb, \u043e\u043f\u044f\u0442\u044c \u043f\u043e\u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u0438\u043b \u0435\u0435, \u0441\u044a\u0435\u043b \u0442\u0430\u0440\u0435\u043b\u043a\u0443 \u0433\u0440\u0435\u0448\u043d\u0435\u0432\u043e\u0439 \u043a\u0430\u0448\u0438\u0446\u044b, \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0432\u0448\u0443\u044e \u0435\u0433\u043e \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u044b\u0439 \u043e\u0431\u0435\u0434; \u043e\u043f\u044f\u0442\u044c \u0443\u0441\u043b\u044b\u0448\u0430\u043b\u202f\u2014\u2009\u044d\u0442\u043e \u0431\u044b\u043b\u043e, \u043d\u0430\u0432\u0435\u0440\u043d\u043e\u0435 \u0447\u0430\u0441\u043e\u0432 \u0432 6, \u043f\u043e\u00a0\u0430\u043a\u043a\u0443\u0440\u0430\u0442\u043d\u043e \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u043e\u043c\u0443 \u0441\u0442\u0430\u0440\u0443\u0448\u043a\u043e\u0439 \u043f\u043e\u0440\u044f\u0434\u043a\u0443,\u202f\u2014\u2009\u0433\u043e\u043b\u043e\u0441 \u0435\u0435 \u00ab\u043f\u0440\u0438\u043d\u0435\u0441\u043b\u0430 \u0441\u0430\u043c\u043e\u0432\u0430\u0440, \u041f\u0430\u0432\u0435\u043b \u0421\u0435\u0440\u0433\u0435\u0438\u0447!\u00bb, \u043e\u043f\u044f\u0442\u044c \u0441\u043a\u0430\u0437\u0430\u043b \u00ab\u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044e \u0432\u0430\u0441, \u0410\u043d\u043d\u0430 \u0414\u0430\u043d\u0438\u043b\u043e\u0432\u043d\u0430\u00bb,\u202f\u2014\u2009\u043d\u043e\u00a0\u0442\u0443\u0442 \u043f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u043e \u043e\u0442\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0435 \u043e\u0442\u00a0\u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u044f\u0434\u043a\u0430: \u0432\u0441\u0442\u0430\u0432 \u043f\u043e\u043b\u043e\u0436\u0438\u0442\u044c \u0447\u0430\u044e \u0432\u00a0\u0447\u0430\u0439\u043d\u0438\u043a, \u0438\u00a0\u043d\u0430\u043b\u0438\u0442\u044c \u043a\u0438\u043f\u044f\u0442\u043a\u043e\u043c, \u041f\u0430\u0432\u0435\u043b \u0421\u0435\u0440\u0433\u0435\u0438\u0447 \u0443\u0432\u0438\u0434\u0435\u043b, \u0447\u0442\u043e\u00a0\u0441\u0442\u0430\u0440\u0443\u0448\u043a\u0430 \u043d\u0435\u00a0\u0443\u0448\u043b\u0430, \u0441\u0442\u043e\u0438\u0442, \u0441\u043b\u043e\u0436\u0430 \u0440\u0443\u043a\u0438"
    val PARTICIPLE_HOST_SPAN = "==Russian==\n\n===Pronunciation===\n* {{ru-IPA|\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0301\u0435\u043c\u044b\u0439}}\n\n===Participle===\n{{head|ru|present passive participle|head=\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0301\u0435\u043c\u044b\u0439}}\n\n# {{participle of|ru|\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0301\u0442\u044c||pres|pass|impfv}}\n\n====Declension====\n{{ru-decl-adj|\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0301\u0435\u043c\u044b\u0439|a}}"

    fun recordId(page: String, span: String): String = page + ":" + span.take(80)

    fun sha256(text: String): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(text.toByteArray(Charsets.UTF_8))
        return digest.joinToString("") { byte -> "%02x".format(byte) }
    }
